(function() {
    'use strict';

    window.Chessboard = function(containerElOrId, config) {
        config = config || {};
        
        var containerEl = typeof containerElOrId === 'string' 
            ? document.getElementById(containerElOrId) 
            : containerElOrId;

        if (!containerEl) {
            console.error('Chessboard: container not found');
            return {};
        }

        var currentPosition = config.position || 'start';
        var orientation = config.orientation || 'white';
        var showNotation = config.showNotation !== false;
        var pieceTheme = config.pieceTheme || function(p) { return ''; };
        var onDragStart = config.onDragStart || function() { return true; };
        var onDrop = config.onDrop || function() { return 'snapback'; };
        var onSnapEnd = config.onSnapEnd || function() {};
        var draggedPiece = null;
        var dragSource = null;
        var boardEl = null;
        var piecesEl = null;
        var isDragging = false;

        function buildBoard() {
            containerEl.innerHTML = '';
            
            boardEl = document.createElement('div');
            boardEl.style.cssText = 'position:relative;width:100%;height:100%;';
            containerEl.appendChild(boardEl);

            // Draw squares
            for (var row = 0; row < 8; row++) {
                for (var col = 0; col < 8; col++) {
                    var square = document.createElement('div');
                    var displayRow = orientation === 'white' ? row : 7 - row;
                    var displayCol = orientation === 'white' ? col : 7 - col;
                    var isLight = (displayRow + displayCol) % 2 === 0;
                    var squareId = String.fromCharCode(97 + displayCol) + (8 - displayRow);
                    
                    square.className = 'square square-' + squareId;
                    square.setAttribute('data-square', squareId);
                    square.style.cssText = 
                        'position:absolute;' +
                        'width:12.5%;height:12.5%;' +
                        'top:' + (row * 12.5) + '%;' +
                        'left:' + (col * 12.5) + '%;' +
                        'background-color:' + (isLight ? '#f0d9b5' : '#b58863') + ';';
                    
                    boardEl.appendChild(square);
                }
            }

            // Notation
            if (showNotation) {
                for (var i = 0; i < 8; i++) {
                    var col = orientation === 'white' ? i : 7 - i;
                    var fileLabel = document.createElement('div');
                    fileLabel.textContent = String.fromCharCode(97 + col);
                    fileLabel.style.cssText = 
                        'position:absolute;bottom:2px;' +
                        'left:' + (i * 12.5 + 6.25) + '%;' +
                        'transform:translateX(-50%);' +
                        'font-size:10px;color:' + (i % 2 === 0 ? '#b58863' : '#f0d9b5') + ';' +
                        'font-weight:bold;pointer-events:none;z-index:1;';
                    boardEl.appendChild(fileLabel);

                    var row = orientation === 'white' ? 7 - i : i;
                    var rankLabel = document.createElement('div');
                    rankLabel.textContent = row + 1;
                    rankLabel.style.cssText = 
                        'position:absolute;right:2px;' +
                        'top:' + (i * 12.5 + 6.25) + '%;' +
                        'transform:translateY(-50%);' +
                        'font-size:10px;color:' + (i % 2 === 0 ? '#f0d9b5' : '#b58863') + ';' +
                        'font-weight:bold;pointer-events:none;z-index:1;';
                    boardEl.appendChild(rankLabel);
                }
            }

            // Pieces container
            piecesEl = document.createElement('div');
            piecesEl.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:2;';
            boardEl.appendChild(piecesEl);
        }

        function placePieces(position) {
            if (!piecesEl) return;
            piecesEl.innerHTML = '';

            var fen = position === 'start' 
                ? 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR' 
                : position.split(' ')[0];

            var rows = fen.split('/');
            for (var row = 0; row < 8; row++) {
                var col = 0;
                for (var i = 0; i < rows[row].length; i++) {
                    var ch = rows[row][i];
                    if (ch >= '0' && ch <= '9') {
                        col += parseInt(ch);
                    } else {
                        var color = ch === ch.toUpperCase() ? 'w' : 'b';
                        var type = ch.toUpperCase();
                        var displayRow = orientation === 'white' ? row : 7 - row;
                        var displayCol = orientation === 'white' ? col : 7 - col;
                        var square = String.fromCharCode(97 + displayCol) + (8 - displayRow);
                        
                        var pieceEl = document.createElement('div');
                        pieceEl.className = 'piece piece-' + color + type;
                        pieceEl.setAttribute('data-piece', color + type);
                        pieceEl.setAttribute('data-square', square);
                        pieceEl.textContent = pieceTheme(color + type);
                        pieceEl.style.cssText = 
                            'position:absolute;' +
                            'width:12.5%;height:12.5%;' +
                            'top:' + (displayRow * 12.5) + '%;' +
                            'left:' + (displayCol * 12.5) + '%;' +
                            'display:flex;align-items:center;justify-content:center;' +
                            'font-size:' + (containerEl.offsetWidth * 0.08) + 'px;' +
                            'cursor:pointer;user-select:none;pointer-events:all;z-index:3;';
                        
                        pieceEl.addEventListener('mousedown', function(e) {
                            dragStart(e.clientX, e.clientY, pieceEl, square, color + type);
                        });
                        pieceEl.addEventListener('touchstart', function(e) {
                            e.preventDefault();
                            var t = e.touches[0];
                            dragStart(t.clientX, t.clientY, pieceEl, square, color + type);
                        });
                        
                        piecesEl.appendChild(pieceEl);
                        col++;
                    }
                }
            }
        }

        function dragStart(x, y, el, square, piece) {
            if (onDragStart(square, piece, currentPosition, orientation) === false) return;
            
            isDragging = true;
            draggedPiece = el;
            dragSource = square;
            el.style.zIndex = '100';
            
            function move(e) {
                var cx = e.clientX || (e.touches && e.touches[0].clientX);
                var cy = e.clientY || (e.touches && e.touches[0].clientY);
                if (!cx || !draggedPiece || !boardEl) return;
                var rect = boardEl.getBoundingClientRect();
                draggedPiece.style.left = ((cx - rect.left) / rect.width * 100 - 6.25) + '%';
                draggedPiece.style.top = ((cy - rect.top) / rect.height * 100 - 6.25) + '%';
            }
            
            function release(e) {
                document.removeEventListener('mousemove', move);
                document.removeEventListener('touchmove', move);
                document.removeEventListener('mouseup', release);
                document.removeEventListener('touchend', release);
                
                var cx = e.clientX || (e.changedTouches && e.changedTouches[0].clientX);
                var cy = e.clientY || (e.changedTouches && e.changedTouches[0].clientY);
                
                if (!boardEl || !cx) {
                    snapback();
                    return;
                }
                
                var rect = boardEl.getBoundingClientRect();
                var col = Math.floor((cx - rect.left) / rect.width * 8);
                var row = Math.floor((cy - rect.top) / rect.height * 8);
                
                var targetSquare = null;
                if (col >= 0 && col < 8 && row >= 0 && row < 8) {
                    var ac = orientation === 'white' ? col : 7 - col;
                    var ar = orientation === 'white' ? 8 - row : row + 1;
                    targetSquare = String.fromCharCode(97 + ac) + ar;
                }
                
                var result = onDrop(dragSource, targetSquare, piece);
                if (result === 'snapback') {
                    snapback();
                }
                
                isDragging = false;
                draggedPiece.style.zIndex = '3';
                draggedPiece = null;
                dragSource = null;
                onSnapEnd();
            }
            
            document.addEventListener('mousemove', move);
            document.addEventListener('touchmove', move, { passive: false });
            document.addEventListener('mouseup', release);
            document.addEventListener('touchend', release);
        }

        function snapback() {
            if (!draggedPiece || !dragSource) return;
            var col = dragSource.charCodeAt(0) - 97;
            var row = 8 - parseInt(dragSource[1]);
            var dr = orientation === 'white' ? row : 7 - row;
            var dc = orientation === 'white' ? col : 7 - col;
            draggedPiece.style.transition = 'all 0.2s ease';
            draggedPiece.style.left = (dc * 12.5) + '%';
            draggedPiece.style.top = (dr * 12.5) + '%';
            setTimeout(function() {
                if (draggedPiece) draggedPiece.style.transition = '';
            }, 200);
        }

        buildBoard();
        placePieces(currentPosition);

        return {
            position: function(pos) {
                if (pos === undefined) return currentPosition;
                currentPosition = pos;
                placePieces(currentPosition);
                return this;
            },
            resize: function() {
                if (!piecesEl) return;
                var size = containerEl.offsetWidth * 0.08;
                var allPieces = piecesEl.querySelectorAll('.piece');
                for (var i = 0; i < allPieces.length; i++) {
                    allPieces[i].style.fontSize = size + 'px';
                }
            },
            destroy: function() {
                containerEl.innerHTML = '';
                boardEl = null;
                piecesEl = null;
            },
            orientation: function(orient) {
                if (orient === undefined) return orientation;
                orientation = orient;
                placePieces(currentPosition);
                return this;
            },
            clear: function() {
                if (piecesEl) piecesEl.innerHTML = '';
            }
        };
    };
})();
